// Wait 60 seconds for Apify to finish scraping
await new Promise(resolve => setTimeout(resolve, 60000));
return $input.all();

const stories = $input.all();
const results = [];

for (const item of stories) {
  const story = item.json;

  const imageUrl = story.displayUrl || (story.images && story.images[0]) || story.imageUrl || '';

  if (!imageUrl) continue;

  const caption = story.caption || story.text || story.alt || '';
  const timestamp = story.timestamp || story.takenAt || new Date().toISOString();
  const storyId = story.id || story.shortCode || story.pk || 'story_' + Date.now();

  results.push({
    json: {
      storyId,
      imageUrl,
      caption,
      timestamp,
      username: story.ownerUsername || story.username || 'ghaith_nutrition10.10',
      mediaType: story.type || story.productType || 'image',
      hasImage: true
    }
  });
}

return results;

const items = $input.all();
const stories = $('📋 Parse Story Data').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const story = (stories[i] && stories[i].json) ? stories[i].json : {};

  let base64Image = null;
  let mimeType = 'image/jpeg';

  if (item.binary && item.binary.data) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
      if (buffer && buffer.length > 0) {
        base64Image = buffer.toString('base64');
      }
    } catch (e) {
      if (typeof item.binary.data.data === 'string' && !item.binary.data.data.startsWith('filesystem')) {
        base64Image = item.binary.data.data;
      }
    }
    mimeType = item.binary.data.mimeType || 'image/jpeg';
  }

  const parts = [];

  if (base64Image && base64Image !== 'filesystem-v2') {
    parts.push({
      inlineData: {
        mimeType: mimeType,
        data: base64Image
      }
    });
  }

  const promptText = `You are an automated product extraction agent for GymPilot, an e-commerce fitness marketplace in Tunisia.
Analyze this Instagram story image and caption from seller Ghaith Nutrition.

CRITICAL INSTRUCTION - ALL OFFERS ARE PACKS PROMO:
In GymPilot, all promotional offers, bundle packs, discounted supplements, and special deals posted by Ghaith Nutrition on Instagram are PACKS PROMO (type: "pack").
Whether it contains 1 supplement with a discount or 2+ bundled supplements, classify it as type = "pack".

RULES:
1. Currency is Tunisian Dinar (TND).
2. Type:
   - If story shows any supplement, offer, promo, combo, or product with a price => type = "pack"
   - If story is pure non-commercial content with NO product and NO price (e.g. gym workout video, meme, quote) => type = "skip"
3. Category:
   - Must be "Packs & Stacks" for all promotional packs/offers.
4. Badge:
   - "PACK PROMO", "FLASH SALE", or "OFFRE LIMITEE"
5. Tagline:
   - Catchy French or Tunisian slogan (e.g. "Pack Force & Masse Musculaire | Stock Limite")

Caption: ${story.caption || 'None'}

Respond strictly with a single JSON object (no markdown, no backticks):
{
  "type": "pack" | "skip",
  "name": "Pack Promo name in French (e.g. Pack Real Mass 3kg + Shaker)",
  "tagline": "Short punchy slogan in French",
  "badge": "PACK PROMO",
  "description": "Engaging description in French highlighting components, benefits and dosage",
  "category": "Packs & Stacks",
  "price": 149.0,
  "originalPrice": 189.0,
  "items": [
    { "name": "Main Supplement Name", "quantity": 1, "description": "High quality protein", "dosage": "1 scoop/day" }
  ]
}`;

  parts.push({ text: promptText });

  results.push({
    json: {
      geminiPayload: {
        contents: [{ parts }],
        generationConfig: {
          temperature: 0.1,
          maxOutputTokens: 1000,
          responseMimeType: 'application/json'
        }
      }
    }
  });
}

return results;

const items = $input.all();
const stories = $('📋 Parse Story Data').all();
const results = [];

const CATEGORY_MAP = {
  'packs & stacks': '6aa3cf01ae84ed74b697583f',
  'pack': '6aa3cf01ae84ed74b697583f',
  'whey protein': '6a985c4550777d3e0a93e601',
  'creatine': '6a985c4550777d3e0a93e602',
  'mass gainer': '6a985c4550777d3e0a93e603',
  'vitamins & supplements': '6a985c4550777d3e0a93e604'
};

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  try {
    const rawContent = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    const cleaned = rawContent.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(cleaned);

    const storyData = (stories[i] && stories[i].json) ? stories[i].json : {};

    // Check if it's pure non-commercial skip
    const isSkip = parsed.type === 'skip' && !parsed.price && !storyData.caption?.match(/\d+\s*(dt|tnd)/i);

    if (isSkip) {
      results.push({ json: { type: 'skip', reason: 'Non-commercial story' } });
      continue;
    }

    // All valid offers from Ghaith Nutrition Instagram stories are PACKS PROMO!
    const name = parsed.name || 'Pack Promo Ghaith Nutrition';
    const price = Number(parsed.price) || 0;
    const originalPrice = parsed.originalPrice ? Number(parsed.originalPrice) : (price > 0 ? Math.round(price * 1.25) : 0);
    const badge = parsed.badge || 'PACK PROMO';
    const tagline = parsed.tagline || 'Offre exclusive Ghaith Nutrition - Stock Limité';

    let packItems = (parsed.items && Array.isArray(parsed.items) && parsed.items.length > 0)
      ? parsed.items
      : [{ name: name, quantity: 1, description: parsed.description || 'Produit 100% authentique', dosage: '1 dose/jour' }];

    results.push({
      json: {
        ...parsed,
        type: 'pack', // Enforce type = pack so it goes directly to Pack Promo
        name: name,
        tagline: tagline,
        badge: badge,
        price: price,
        originalPrice: originalPrice,
        items: packItems,
        category: 'Packs & Stacks',
        categoryId: '6aa3cf01ae84ed74b697583f',
        storyId: storyData.storyId || 'story_' + Date.now(),
        imageUrl: storyData.imageUrl || '',
        caption: storyData.caption || ''
      }
    });
  } catch (e) {
    results.push({
      json: {
        type: 'skip',
        error: 'Failed to parse Gemini response: ' + e.message
      }
    });
  }
}

return results;

