const items = $input.all();
const results = [];

// Ensure we have a valid token for GymPilot API
let token = '';
try {
  token = $('🔐 GymPilot Login').first()?.json?.token;
} catch (e) {}

if (!token) {
  try {
    const res = await fetch('https://api.gympilot.tn/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: 'iskander.skan05@gmail.com',
        password: 'Topadmin2005'
      })
    });
    const data = await res.json();
    token = data.token;
  } catch (e) {
    console.error('GymPilot login fallback error:', e);
  }
}

for (const item of items) {
  const data = item.json;
  const name = data.name || 'Pack Promo Ghaith Nutrition';
  const category = data.category || 'Packs & Stacks';

  const itemsList = (data.items && Array.isArray(data.items))
    ? data.items.map(i => i.name).filter(Boolean).join(', ')
    : name;

  const prompt = `Commercial 3D e-commerce studio photography of a premium fitness supplement bundle pack: ${itemsList || name}. Premium matte black and neon lime supplement tubs, shaker bottle, displayed on a clean dark reflective carbon surface, soft gym background bokeh, dynamic neon edge lighting, ultra-realistic, 8k resolution, crisp photorealistic mockup`;

  const encodedPrompt = encodeURIComponent(prompt.trim());
  const hash = Math.abs(name.split('').reduce((acc, char) => (acc << 5) - acc + char.charCodeAt(0), 0)) % 1000000;

  // 1. Square image (1024x1024) for Boutique e-commerce cards
  const shopImageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1024&height=1024&model=flux&seed=${hash}&nologo=true`;

  // 2. Vertical 9:16 image (1080x1920) specifically optimized for Instagram Stories
  const storyImageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1080&height=1920&model=flux&seed=${hash}&nologo=true`;

  const images = [shopImageUrl];
  if (storyImageUrl) images.push(storyImageUrl);
  if (data.imageUrl && data.imageUrl.startsWith('http')) {
    images.push(data.imageUrl);
  }

  results.push({
    json: {
      ...data,
      token: token || data.token,
      aiImageUrl: shopImageUrl,
      storyImageUrl: storyImageUrl, // 9:16 vertical visual for Instagram Story
      generatedPrompt: prompt,
      images
    }
  });
}

return results;

const pack = $json;
const name = pack.name || 'Pack Spécial Ghaith Nutrition';
const price = pack.price ? `${pack.price} DT` : '';
const shopUrl = `https://gympilot.tn/shop/pack/${pack.slug || pack.id || ''}`;

// Use 9:16 story image, fallback to primary image, fallback to story snapshot
const storyImageUrl = pack.storyImageUrl || (pack.images && pack.images.length > 1 ? pack.images[1] : (pack.images && pack.images[0])) || pack.imageUrl || '';

return [{
  json: {
    packId: pack.id,
    packName: name,
    price: price,
    shopUrl: shopUrl,
    storyImageUrl: storyImageUrl
  }
}];

